<?php

namespace App\Traits;

trait HtmlSanitizer
{
    /**
     * Allowed HTML tags for rich content generated by Quill/WYSIWYG editor.
     */
    protected const ALLOWED_HTML_TAGS = [
        'p', 'br', 'strong', 'b', 'em', 'i', 'u', 's', 'strike', 'del',
        'blockquote', 'ol', 'ul', 'li', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
        'a', 'img', 'pre', 'code', 'table', 'thead', 'tbody', 'tfoot', 'tr',
        'th', 'td', 'hr', 'div', 'span', 'sub', 'sup'
    ];

    /**
     * Sanitize HTML content to prevent Stored XSS and malicious script execution.
     */
    protected function sanitizeHtml(string $html): string
    {
        if (trim($html) === '') {
            return '';
        }

        // 1. Remove dangerous container tags along with their inner content FIRST
        $html = preg_replace('#<(script|style|iframe|object|embed|applet|meta|form|input|button|svg|math|base|link)\b[^>]*>.*?</\1>#is', '', $html) ?? $html;
        $html = preg_replace('#<(script|style|iframe|object|embed|applet|meta|form|input|button|svg|math|base|link)\b[^>]*>#is', '', $html) ?? $html;

        // 2. Strip all non-whitelisted tags
        $html = strip_tags($html, self::ALLOWED_HTML_TAGS);

        // 3. Multi-pass cleanup to avoid evasion via nesting
        $maxPasses = 5;
        $pass = 0;

        do {
            $original = $html;
            $pass++;

            // Remove any leftover dangerous container tags along with their inner content
            $html = preg_replace('#<(script|style|iframe|object|embed|applet|meta|form|input|button|svg|math|base|link)\b[^>]*>.*?</\1>#is', '', $html) ?? $html;
            $html = preg_replace('#<(script|style|iframe|object|embed|applet|meta|form|input|button|svg|math|base|link)\b[^>]*>#is', '', $html) ?? $html;

            // Remove all inline event handlers (e.g. onload, onerror, onclick, onmouseover)
            // Handles variations with whitespace, tabs, newlines, or forward slashes (e.g. <img/src=x/onerror=...>)
            $html = preg_replace('#(?:\s|/|^)on[a-z0-9_-]+\s*=\s*(?:"[^"]*"|\'[^\']*\'|[^\s>]+)#is', '', $html) ?? $html;

            // Remove javascript:, vbscript:, and non-image data: URIs in attributes
            $html = preg_replace_callback('#(href|src|action|formaction|data)\s*=\s*(["\'])(.*?)\2#is', function ($matches) {
                $attr = strtolower($matches[1]);
                $quote = $matches[2];
                $val = $matches[3];

                // Decode HTML entities to detect hidden protocols
                $decoded = html_entity_decode($val, ENT_QUOTES | ENT_HTML5, 'UTF-8');
                $normalizedProtocol = strtolower(preg_replace('/[\x00-\x20\s]+/', '', $decoded));

                if (str_starts_with($normalizedProtocol, 'javascript:') || str_starts_with($normalizedProtocol, 'vbscript:')) {
                    return '';
                }

                if (str_starts_with($normalizedProtocol, 'data:') && !preg_match('#^data:image\/(png|jpe?g|webp|gif);base64,#i', $normalizedProtocol)) {
                    return '';
                }

                return "{$attr}={$quote}{$val}{$quote}";
            }, $html) ?? $html;

            // Unquoted attribute cleanup
            $html = preg_replace('#(href|src|action|formaction|data)\s*=\s*(?:javascript|vbscript|data(?!\s*:\s*image\/(?:png|jpeg|jpg|webp|gif)))[^\s>]*#is', '', $html) ?? $html;

        } while ($html !== $original && $pass < $maxPasses);

        return trim($html);
    }
}

